// Playback table for HeroCharacter, generated by .agents/scripts/build_hero_frames.py from the five
// magenta clips (loop, greeting, glances, two side-to-viewer bridges).
// Every frame is a node, played forwards or (glance clip only) backwards. For each goal the table
// gives every node the next node on the quickest seamless way there, measured offline: cuts between
// clips only where the frames differ no more than the motion around them, no crossfades, no held
// frames. The player follows it one frame per tick, so a reaction starts at once from anywhere.
// relative + import attribute so the Node check script can load this file as is
import graph from "./heroGraph.json" with { type: "json" };

export type Goal = "work" | "right" | "left" | "greet";

export const FRAMES: number = graph.frames;
export const LOOP: number = graph.loop; // frames 1..LOOP are the working loop
export const RIGHT: number = graph.right; // deep in the right-look hold: arriving here, he heads back to work
export const LEFT: number = graph.left;
export const WAVE: number = graph.wave;
export const POINT: number = graph.point;
export const LAST: number = graph.last; // greeting's last frame: he holds the point
export const PHONE: number[] = graph.phone; // frames phones can reach (no glances)

// node = 2 * (frame - 1) + (1 when playing backwards)
export const START = 0; // frame 1 (the hub), forwards
export const frameOf = (node: number) => (node >> 1) + 1;
/** The node after `node` on the way to `goal` (the same node when there is nowhere further to go). */
export const step = (node: number, goal: Goal) => {
  const n = graph.next[goal][node];
  return n < 0 ? node : n;
};

/** Goal after showing `frame`: a glance turns back to work once it reaches its hold. */
export const arrive = (frame: number, goal: Goal): Goal =>
  (goal === "right" && frame === RIGHT) || (goal === "left" && frame === LEFT) ? "work" : goal;
